19: function ensureFileIsPassed ({ file }: Request, res: Response, next: NextFunction) {
20:   if (file != null) {
21:     next()
22:   } else {
23:     return res.status(400).json({ error: 'File is not passed' })
24:   }
25: }
26: 
27: async function extractZipBuffer (buffer: Buffer) {
28:   const directory = await unzipper.Open.buffer(buffer)
29:   for (const entry of directory.files) {
30:     const fileName = entry.path
31:     const absolutePath = path.resolve('uploads/complaints/' + fileName)
32:     challengeUtils.solveIf(challenges.fileWriteChallenge, () => { return absolutePath === path.resolve('ftp/legal.md') })
33:     if (absolutePath.includes(path.resolve('.'))) {
34:       await pipeline(entry.stream(), fs.createWriteStream('uploads/complaints/' + fileName))
35:     }
36:   }
37: }
38: 
39: async function handleZipFileUpload ({ file }: Request, res: Response, next: NextFunction) {
40:   if (!(file?.originalname?.toLowerCase().endsWith('.zip') ?? false)) {
41:     next()
42:     return
43:   }
44:   if (((file?.buffer) != null) && utils.isChallengeEnabled(challenges.fileWriteChallenge)) {
45:     try {
46:       await extractZipBuffer(file.buffer)
47:     } catch (err) {
48:       next(err)
49:       return
50:     }
51:   }
52:   res.status(204).end()
53: }
54: 
55: function checkUploadSize ({ file }: Request, res: Response, next: NextFunction) {
56:   if (file != null) {
57:     challengeUtils.solveIf(challenges.uploadSizeChallenge, () => { return file?.size > 100000 })
58:   }
59:   next()
60: }
61: 
62: function checkFileType ({ file }: Request, res: Response, next: NextFunction) {
63:   const fileType = file?.originalname.substr(file.originalname.lastIndexOf('.') + 1).toLowerCase()
64:   challengeUtils.solveIf(challenges.uploadTypeChallenge, () => {
65:     return !(fileType === 'pdf' || fileType === 'xml' || fileType === 'zip' || fileType === 'yml' || fileType === 'yaml')
66:   })
67:   next()
68: }
69: 
70: async function handleXmlUpload ({ file }: Request, res: Response, next: NextFunction) {
71:   if (file?.originalname?.toLowerCase().endsWith('.xml') ?? false) {
72:     challengeUtils.solveIf(challenges.deprecatedInterfaceChallenge, () => { return true })
73:     if (((file?.buffer) != null) && utils.isChallengeEnabled(challenges.deprecatedInterfaceChallenge)) { // XXE attacks in Docker/Heroku containers regularly cause "segfault" crashes
74:       const data = file.buffer.toString()
75:       try {
76:         const xmlString = await parseXmlString(data)
77:         challengeUtils.solveIf(challenges.xxeFileDisclosureChallenge, () => { return (utils.matchesEtcPasswdFile(xmlString) || utils.matchesSystemIniFile(xmlString)) })
78:         res.status(410)
79:         next(new Error('B2B customer complaints via file upload have been deprecated for security reasons: ' + utils.trunc(xmlString, 400) + ' (' + file.originalname + ')'))
80:       } catch (err: unknown) {
81:         const errorMessage = err instanceof Error ? err.message : String(err)
82:         if (errorMessage.includes('Script execution timed out')) {
83:           if (challengeUtils.notSolved(challenges.xxeDosChallenge)) {
84:             challengeUtils.solve(challenges.xxeDosChallenge)
85:           }
86:           res.status(503)
87:           next(new Error('Sorry, we are temporarily not available! Please try again later.'))
88:         } else {
89:           res.status(410)
90:           next(new Error('B2B customer complaints via file upload have been deprecated for security reasons: ' + errorMessage + ' (' + file.originalname + ')'))
91:         }
92:       }
93:     } else {
94:       res.status(410)
95:       next(new Error('B2B customer complaints via file upload have been deprecated for security reasons (' + file?.originalname + ')'))
96:     }
97:   }
98:   next()
99: }
100: 
101: function handleYamlUpload ({ file }: Request, res: Response, next: NextFunction) {
102:   if ((file?.originalname?.toLowerCase().endsWith('.yml') ?? false) || (file?.originalname?.toLowerCase().endsWith('.yaml') ?? false)) {
103:     challengeUtils.solveIf(challenges.deprecatedInterfaceChallenge, () => { return true })
104:     if (((file?.buffer) != null) && utils.isChallengeEnabled(challenges.deprecatedInterfaceChallenge)) {
105:       const data = file.buffer.toString()
106:       try {
107:         const sandbox = { yaml, data }
108:         vm.createContext(sandbox)
109:         const yamlString = vm.runInContext('JSON.stringify(yaml.load(data))', sandbox, { timeout: 2000 })
110:         res.status(410)
111:         next(new Error('B2B customer complaints via file upload have been deprecated for security reasons: ' + utils.trunc(yamlString, 400) + ' (' + file.originalname + ')'))
112:       } catch (err: unknown) {
113:         const errorMessage = err instanceof Error ? err.message : String(err)
114:         if (errorMessage.includes('Invalid string length') || errorMessage.includes('Script execution timed out')) {
115:           if (challengeUtils.notSolved(challenges.yamlBombChallenge)) {
116:             challengeUtils.solve(challenges.yamlBombChallenge)
117:           }
118:           res.status(503)
119:           next(new Error('Sorry, we are temporarily not available! Please try again later.'))
120:         } else {
121:           res.status(410)
122:           next(new Error('B2B customer complaints via file upload have been deprecated for security reasons: ' + errorMessage + ' (' + file.originalname + ')'))
123:         }
124:       }
125:     } else {
126:       res.status(410)
127:       next(new Error('B2B customer complaints via file upload have been deprecated for security reasons (' + file?.originalname + ')'))
128:     }
129:   }
130:   res.status(204).end()

